enable_vencord_theme() {
  local settings_file="$1"
  local theme_name="quickshell-theme.css"

  [ -f "$settings_file" ] || return 0
  command -v perl >/dev/null 2>&1 || return 0

  local tmp_file
  tmp_file="$(mktemp)"

  if THEME_NAME="$theme_name" perl -0 -pe '
    my $theme = $ENV{THEME_NAME};
    if (!/"enabledThemes"\s*:\s*\[[^\]]*"\Q$theme\E"[^\]]*\]/s) {
      s/("enabledThemes"\s*:\s*\[\s*)(\])/$1\n        "$theme"\n    $2/s
        or s/("enabledThemes"\s*:\s*\[)(.*?)(\s*\])/$1$2,\n        "$theme"$3/s;
    }
  ' "$settings_file" > "$tmp_file"; then
    mv "$tmp_file" "$settings_file"
  else
    rm -f "$tmp_file"
  fi
}
